from click._compat import term_len
from click.formatting import wrap_text

class FakeFormatter:
    def __init__(self):
        self.outputs = []
    def self_write(self, s):
        self.outputs.append(s)

def write_usage_fixed(prog, args='', prefix='Usage: ', width=80):
    usage_prefix = f'{prefix:>{0}}{prog} '
    text_width = width

    formatter = FakeFormatter()

    if args:
        if text_width >= (term_len(usage_prefix) + 20):
            indent = ' ' * term_len(usage_prefix)
            formatter.self_write(
                wrap_text(
                    args,
                    text_width,
                    initial_indent=usage_prefix,
                    subsequent_indent=indent,
                )
            )
        else:
            formatter.self_write(usage_prefix)
            formatter.self_write('\n')
            indent = ' ' * (max(0, term_len(prefix)) + 4)
            formatter.self_write(
                wrap_text(
                    args, text_width, initial_indent=indent, subsequent_indent=indent
                )
            )
        # Write final newline for non-empty args
        formatter.self_write('\n')
    else:
        # Empty args case
        formatter.self_write(usage_prefix.rstrip())
        formatter.self_write('\n')

    return ''.join(formatter.outputs)

